			y = endPosition.y;
			z = ExtendedLerp(hat.hatSO.droneFlyHeight, hat.hatSO.droneFlyHeight + 1f, droneSO.flipZCuve.Evaluate(num)) + endPosition.z;
			q = Quaternion.AngleAxis(ExtendedLerp(0f, 360f, EaseOutCubic(num)), Vector3.right);
			break;
